=head2 Google::Cloud::Networkmanagement::V1beta1::Trace::FirewallInfo

For display only. Metadata associated with a VPC firewall rule, an implied
VPC firewall rule, or a firewall policy rule.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->display_name() >> / C<< $msg->display_name($value) >>

Type: C<String>

The display name of the firewall rule. This field might be empty for
firewall policy rules.

=item * C<< $msg->uri() >> / C<< $msg->uri($value) >>

Type: C<String>

The URI of the firewall rule in format
"projects/{project}/global/firewalls/{firewall}". This field is not
applicable to implied VPC firewall rules.

=item * C<< $msg->direction() >> / C<< $msg->direction($value) >>

Type: C<String>

Possible values: INGRESS, EGRESS

=item * C<< $msg->action() >> / C<< $msg->action($value) >>

Type: C<String>

Possible values: ALLOW, DENY, APPLY_SECURITY_PROFILE_GROUP

=item * C<< $msg->priority() >> / C<< $msg->priority($value) >>

Type: C<Int32>

The priority of the firewall rule.

=item * C<< $msg->network_uri() >> / C<< $msg->network_uri($value) >>

Type: C<String>

The URI of the VPC network that the firewall rule is associated with in
format "projects/{project}/global/networks/{network}".
This field is not applicable to hierarchical firewall policy rules.

=item * C<< $msg->target_tags() >> / C<< $msg->target_tags($value) >>

Type: C<String>

The target tags defined by the VPC firewall rule. This field is not
applicable to firewall policy rules.

=item * C<< $msg->target_service_accounts() >> / C<< $msg->target_service_accounts($value) >>

Type: C<String>

The target service accounts specified by the firewall rule.

=item * C<< $msg->policy() >> / C<< $msg->policy($value) >>

Type: C<String>

The name of the firewall policy that this rule is associated with.
This field is not applicable to VPC firewall rules and implied VPC firewall
rules.

=item * C<< $msg->policy_uri() >> / C<< $msg->policy_uri($value) >>

Type: C<String>

The URI of the firewall policy that this rule is associated with.
This field is not applicable to VPC firewall rules and implied VPC firewall
rules.
Format:
* `locations/global/firewallPolicies/{policy_id}` (hierarchical policy)
* `projects/{project_id}/global/firewallPolicies/{policy_id}` (global
network firewall policy)
* `projects/{project_id}/regions/{region}/firewallPolicies/{policy_id}`
(regional network firewall policy)

=item * C<< $msg->firewall_rule_type() >> / C<< $msg->firewall_rule_type($value) >>

Type: C<Enum> (L<Google::Cloud::Networkmanagement::V1beta1::FirewallInfo::FirewallRuleType>)

The firewall rule's type.

=item * C<< $msg->policy_priority() >> / C<< $msg->policy_priority($value) >>

Type: C<Int32>

The priority of the firewall policy that this rule is associated with.
This field is not applicable to VPC firewall rules and implied VPC firewall
rules.

=item * C<< $msg->target_type() >> / C<< $msg->target_type($value) >>

Type: C<Enum> (L<Google::Cloud::Networkmanagement::V1beta1::FirewallInfo::TargetType>)

Target type of the firewall rule.

=back

