=head2 Google::Cloud::Networkmanagement::V1beta1::Trace::RouteInfo

For display only. Metadata associated with a Compute Engine route.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->route_type() >> / C<< $msg->route_type($value) >>

Type: C<Enum> (L<Google::Cloud::Networkmanagement::V1beta1::RouteInfo::RouteType>)

Type of route.

=item * C<< $msg->next_hop_type() >> / C<< $msg->next_hop_type($value) >>

Type: C<Enum> (L<Google::Cloud::Networkmanagement::V1beta1::RouteInfo::NextHopType>)

Type of next hop.

=item * C<< $msg->route_scope() >> / C<< $msg->route_scope($value) >>

Type: C<Enum> (L<Google::Cloud::Networkmanagement::V1beta1::RouteInfo::RouteScope>)

Indicates where route is applicable. Deprecated, routes with NCC_HUB scope
are not included in the trace in new tests.

=item * C<< $msg->display_name() >> / C<< $msg->display_name($value) >>

Type: C<String>

Name of a route.

=item * C<< $msg->uri() >> / C<< $msg->uri($value) >>

Type: C<String>

URI of a route in format
"projects/{project}/global/routes/{route}". SUBNET, STATIC,
PEERING_SUBNET (only for peering network) and POLICY_BASED routes only.

=item * C<< $msg->region() >> / C<< $msg->region($value) >>

Type: C<String>

Region of the route. DYNAMIC, PEERING_DYNAMIC, POLICY_BASED and ADVERTISED
routes only. If set for POLICY_BASED route, this is a region of VLAN
attachments for Cloud Interconnect the route applies to. If set to "all"
for POLICY_BASED route, the route applies to VLAN attachments of Cloud
Interconnect in all regions.

=item * C<< $msg->dest_ip_range() >> / C<< $msg->dest_ip_range($value) >>

Type: C<String>

Destination IP range of the route.

=item * C<< $msg->next_hop() >> / C<< $msg->next_hop($value) >>

Type: C<String>

String type of the next hop of the route (for example, "VPN tunnel").
Deprecated in favor of the next_hop_type and next_hop_uri fields, not used
in new tests.

=item * C<< $msg->network_uri() >> / C<< $msg->network_uri($value) >>

Type: C<String>

URI of a VPC network where route is located in format
"projects/{project}/global/networks/{network}".

=item * C<< $msg->priority() >> / C<< $msg->priority($value) >>

Type: C<Int32>

Priority of the route.

=item * C<< $msg->instance_tags() >> / C<< $msg->instance_tags($value) >>

Type: C<String>

Instance tags of the route.

=item * C<< $msg->src_ip_range() >> / C<< $msg->src_ip_range($value) >>

Type: C<String>

Source IP address range of the route. POLICY_BASED routes only.

=item * C<< $msg->dest_port_ranges() >> / C<< $msg->dest_port_ranges($value) >>

Type: C<String>

Destination port ranges of the route. POLICY_BASED routes only.

=item * C<< $msg->src_port_ranges() >> / C<< $msg->src_port_ranges($value) >>

Type: C<String>

Source port ranges of the route. POLICY_BASED routes only.

=item * C<< $msg->protocols() >> / C<< $msg->protocols($value) >>

Type: C<String>

Protocols of the route. POLICY_BASED routes only.

=item * C<< $msg->ncc_hub_uri() >> / C<< $msg->ncc_hub_uri($value) >>

Type: C<String>

URI of the NCC Hub the route is advertised by in format
"projects/{project}/locations/global/hubs/{hub}". PEERING_SUBNET and
PEERING_DYNAMIC routes that are advertised by NCC Hub only.

=item * C<< $msg->ncc_spoke_uri() >> / C<< $msg->ncc_spoke_uri($value) >>

Type: C<String>

URI of the destination NCC Spoke in format
"projects/{project}/locations/{location}/spokes/{spoke}" (regional) or
"projects/{project}/locations/global/spokes/{spoke}" (global).
PEERING_SUBNET and PEERING_DYNAMIC routes that are advertised by NCC Hub
only.

=item * C<< $msg->advertised_route_source_router_uri() >> / C<< $msg->advertised_route_source_router_uri($value) >>

Type: C<String>

For ADVERTISED dynamic routes, the URI of the Cloud Router that advertised
the corresponding IP prefix in format
"projects/{project}/regions/{region}/routers/{router}".

=item * C<< $msg->advertised_route_next_hop_uri() >> / C<< $msg->advertised_route_next_hop_uri($value) >>

Type: C<String>

For ADVERTISED routes, the URI of their next hop, i.e. the URI of the
hybrid endpoint (VPN tunnel, Interconnect attachment, NCC router appliance)
the advertised prefix is advertised through, or URI of the source peered
network. Deprecated in favor of the next_hop_uri field, not used in new
tests.

=item * C<< $msg->next_hop_uri() >> / C<< $msg->next_hop_uri($value) >>

Type: C<String>

URI of the next hop resource.

=item * C<< $msg->next_hop_network_uri() >> / C<< $msg->next_hop_network_uri($value) >>

Type: C<String>

URI of a VPC network where the next hop resource is located in format
"projects/{project}/global/networks/{network}".

=item * C<< $msg->originating_route_uri() >> / C<< $msg->originating_route_uri($value) >>

Type: C<String>

For PEERING_SUBNET and PEERING_STATIC routes, the URI of the originating
SUBNET/STATIC route.
Format: `projects/{project_id}/global/routes/{route_id}`

=item * C<< $msg->originating_route_display_name() >> / C<< $msg->originating_route_display_name($value) >>

Type: C<String>

For PEERING_SUBNET, PEERING_STATIC and PEERING_DYNAMIC routes, the name of
the originating SUBNET/STATIC/DYNAMIC route.

=item * C<< $msg->ncc_hub_route_uri() >> / C<< $msg->ncc_hub_route_uri($value) >>

Type: C<String>

For PEERING_SUBNET and PEERING_DYNAMIC routes that are advertised by NCC
Hub, the URI of the corresponding route in NCC Hub's routing table.
Format:
`projects/{project_id}/locations/global/hubs/{hub_id}/routeTables/{route_table_id}/routes/{route_id}`

=back

