For display only. Metadata associated with a Compute Engine forwarding rule.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->display_name() >> / C<< $msg->display_name($value) >>

Type: C<String>

Name of the forwarding rule.

=item * C<< $msg->uri() >> / C<< $msg->uri($value) >>

Type: C<String>

URI of the forwarding rule in format
"projects/{project}/global/forwardingRules/{forwarding_rule}" (global) or
"projects/{project}/regions/{region}/forwardingRules/{forwarding_rule}"
(regional).

=item * C<< $msg->matched_protocol() >> / C<< $msg->matched_protocol($value) >>

Type: C<String>

Protocol defined in the forwarding rule that matches the packet.

=item * C<< $msg->matched_port_range() >> / C<< $msg->matched_port_range($value) >>

Type: C<String>

Port range defined in the forwarding rule that matches the packet.

=item * C<< $msg->vip() >> / C<< $msg->vip($value) >>

Type: C<String>

VIP of the forwarding rule.

=item * C<< $msg->target() >> / C<< $msg->target($value) >>

Type: C<String>

Target type of the forwarding rule.

=item * C<< $msg->network_uri() >> / C<< $msg->network_uri($value) >>

Type: C<String>

URI of a VPC network where the forwarding rule is located in format
