Type: C<String>

URI of the PSC service attachment this PSC NEG backend targets (if
applicable) in format
"projects/{project}/regions/{region}/serviceAttachments/{service_attachment}".

=item * C<< $msg->psc_google_api_target() >> / C<< $msg->psc_google_api_target($value) >>

Type: C<String>

PSC Google API target this PSC NEG backend targets (if applicable).

=item * C<< $msg->health_check_uri() >> / C<< $msg->health_check_uri($value) >>

Type: C<String>

URI of the health check attached to this backend (if applicable).
Format:
* `projects/{project_id}/global/healthChecks/{health_check_id}`
* `projects/{project_id}/regions/{region}/healthChecks/{health_check_id}`
* `projects/{project_id}/global/httpHealthChecks/{health_check_id}`
(legacy)

=item * C<< $msg->health_check_firewalls_config_state() >> / C<< $msg->health_check_firewalls_config_state($value) >>

Type: C<Enum> (L<Google::Cloud::Networkmanagement::V1beta1::LoadBalancerBackendInfo::HealthCheckFirewallsConfigState>)

Output only. Health check firewalls configuration state for the backend.
This is a result of the static firewall analysis (verifying that health
check traffic from required IP ranges to the backend is allowed or not).
The backend might still be unhealthy even if these firewalls are
configured. Please refer to the documentation for more information:
https://cloud.google.com/load-balancing/docs/firewall-rules

=back

=head3 Enum: LoadBalancerBackendInfo::HealthCheckFirewallsConfigState

