=item * C<FIREWALLS_CONFIGURED> => C<1>

=item * C<FIREWALLS_PARTIALLY_CONFIGURED> => C<2>

=item * C<FIREWALLS_NOT_CONFIGURED> => C<3>

=item * C<FIREWALLS_UNSUPPORTED> => C<4>

=back

